package com.quincaisoft.operations.application;
import com.quincaisoft.operations.api.RecoveryService;
import com.quincaisoft.operations.infrastructure.*;
import com.quincaisoft.shared.*;
import com.quincaisoft.audit.api.AuditService;
import jakarta.persistence.*;
import org.springframework.stereotype.Service;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.context.SecurityContextHolder;
import tools.jackson.databind.json.JsonMapper;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.*;
import java.util.function.*;

@Service
public class DefaultRecoveryService implements RecoveryService {
 private final EntityManager em;private final ScopedTransactions tx;private final TenantLifecyclePolicy lifecycle;private final AuditService audit;private final OperationReceipts receipts;
 public DefaultRecoveryService(EntityManager em,ScopedTransactions tx,TenantLifecyclePolicy lifecycle,AuditService audit,JsonMapper json){this.em=em;this.tx=tx;this.lifecycle=lifecycle;this.audit=audit;receipts=new OperationReceipts(em,json);}
 private void authorize(String permission){var auth=SecurityContextHolder.getContext().getAuthentication();if(auth==null||!auth.isAuthenticated()||auth.getAuthorities().stream().noneMatch(a->a.getAuthority().equals(permission)||a.getAuthority().equals("SCOPE_"+permission)))throw new AccessDeniedException("Recovery capability required");var s=TenantContext.current();var roles=em.createNativeQuery("select role_code from tenant_memberships where tenant_id=:t and company_id=:c and branch_id=:b and actor_id=:a and active and authorization_epoch=:e").setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("a",s.actorId()).setParameter("e",TenantContext.authorizationEpoch()).getResultList();if(roles.size()!=1||!Set.of("owner","finance").contains(roles.getFirst()))throw new AccessDeniedException("Current branch owner or finance recovery authority required");}
 public Plan request(Request input){if(input==null||input.targetPoint()==null||input.targetPoint().isAfter(Instant.now()))throw new IllegalArgumentException("Past target point required");text(input.incidentReference(),240);text(input.sourceArtifactReference(),1000);text(input.preservationReason(),2000);text(input.reason(),2000);return tx.execute(()->{authorize("operations:recovery:write");return command(input.operationId(),"RecoveryPlanRequested",input,Plan.class,input.reason(),()->{var p=new RecoveryPlan();p.scope(UUID.randomUUID());p.incidentReference=input.incidentReference();p.targetPoint=input.targetPoint().truncatedTo(ChronoUnit.MICROS);p.sourceArtifactReference=input.sourceArtifactReference();p.preservationReason=input.preservationReason();p.status="REQUESTED";p.createdAt=Instant.now().truncatedTo(ChronoUnit.MICROS);em.persist(p);em.flush();return view(p);},Plan::id);});}
 public Plan get(UUID id){return tx.execute(()->{authorize("operations:recovery:read");return view(find(id,LockModeType.NONE));});}
 public List<Plan> list(int offset,int limit){bounds(offset,limit);return tx.execute(()->{authorize("operations:recovery:read");return em.createQuery("select p from RecoveryPlan p order by p.createdAt desc,p.id",RecoveryPlan.class).setFirstResult(offset).setMaxResults(limit).getResultList().stream().map(this::view).toList();});}
 public Plan approveScope(UUID id,Review input){review(input);return tx.execute(()->{authorize("operations:recovery:approve");return command(input.operationId(),"RecoveryScopeApproved",List.of(id,input),Plan.class,input.reason(),()->{var p=find(id,LockModeType.PESSIMISTIC_WRITE);version(p,input.version());if(!p.status.equals("REQUESTED"))throw new IllegalStateException("Pending scope required");independent(p);p.scopeApprovedBy=TenantContext.current().actorId();p.status="COLLECTING";em.flush();return view(p);},Plan::id);});}
 public ReceiptPage retainedReceipts(Instant asOf,UUID after,int limit){if(asOf==null||asOf.isAfter(Instant.now())||limit<1||limit>500)throw new IllegalArgumentException("Past snapshot time and page limit 1..500 required");return tx.execute(()->{authorize("operations:recovery:read");var s=TenantContext.current();String q="select operation_id,request_hash,source_type,source_id,response_digest from recovery_retained_receipt_v1 where tenant_id=:t and company_id=:c and branch_id=:b and created_at<=:cut"+(after==null?"":" and operation_id>:after")+" order by operation_id";var query=em.createNativeQuery(q).setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("cut",asOf).setMaxResults(limit+1);if(after!=null)query.setParameter("after",after);List<?> rows=query.getResultList();boolean more=rows.size()>limit;var result=new ArrayList<Receipt>();for(var object:rows.subList(0,Math.min(rows.size(),limit))){var r=(Object[])object;result.add(new Receipt((UUID)r[0],(String)r[1],(String)r[2],(UUID)r[3],(String)r[4]));}return new ReceiptPage(asOf,List.copyOf(result),more?result.getLast().operationId():null,more);});}
 public Plan append(UUID id,Batch input){if(input==null||input.sequence()<0||input.receipts()==null||input.receipts().isEmpty()||input.receipts().size()>500)throw new IllegalArgumentException("Sequential batch of 1..500 receipts required");text(input.reason(),2000);number(input.version());var ids=new HashSet<UUID>();for(var r:input.receipts()){if(r==null||r.operationId()==null||!ids.add(r.operationId()))throw new IllegalArgumentException("Unique receipt operation identities required");hash(r.requestHash());if(r.responseDigest()!=null)hash(r.responseDigest());if(r.sourceType()!=null&&(r.sourceType().length()>120||r.sourceType().indexOf('\0')>=0||r.sourceType().startsWith("Recovery")))throw new IllegalArgumentException("Invalid source type");}return tx.execute(()->{authorize("operations:recovery:write");return command(input.operationId(),"RecoveryCandidateBatch",List.of(id,input),Plan.class,input.reason(),()->{
  var p=find(id,LockModeType.PESSIMISTIC_WRITE);version(p,input.version());if(!p.status.equals("COLLECTING")||p.nextBatch!=input.sequence())throw new IllegalStateException("Current collecting sequence required");if(!p.actorId.equals(TenantContext.current().actorId()))throw new AccessDeniedException("Only plan maker can upload candidate evidence");if(Math.addExact(p.candidateCount,input.receipts().size())>1_000_000)throw new IllegalArgumentException("Candidate exceeds reviewed one-million-receipt limit");
  for(var r:input.receipts()){var row=new CandidateRecoveryReceipt();row.scope(UUID.randomUUID());row.planId=id;row.operationId=r.operationId();row.requestHash=r.requestHash();row.sourceType=r.sourceType();row.sourceId=r.sourceId();row.responseDigest=r.responseDigest();em.persist(row);}p.candidateCount=Math.addExact(p.candidateCount,input.receipts().size());p.nextBatch=Math.incrementExact(p.nextBatch);em.flush();return view(p);
 },Plan::id);});}
 private static final String COMPARISON="""
 with live as (select operation_id,request_hash,source_type,source_id,response_digest from recovery_retained_receipt_v1
   where tenant_id=:t and company_id=:c and branch_id=:b and created_at<=:cut),
 candidate as(select operation_id,request_hash,source_type,source_id,response_digest from recovery_candidate_receipt where tenant_id=:t and company_id=:c and branch_id=:b and plan_id=:plan),
 classified as(select coalesce(l.operation_id,r.operation_id) operation_id,l.request_hash live_hash,r.request_hash candidate_hash,
   case when l.operation_id is null then 'EXTRA_IN_CANDIDATE' when r.operation_id is null then 'MISSING_FROM_CANDIDATE'
   when l.response_digest is null or r.response_digest is null then 'RESPONSE_EVIDENCE_UNAVAILABLE'
   when l.request_hash is distinct from r.request_hash or l.source_type is distinct from r.source_type or l.source_id is distinct from r.source_id or l.response_digest is distinct from r.response_digest then 'CONTENT_CONFLICT' else null end classification
   from live l full join candidate r on l.operation_id=r.operation_id),
 inserted as(insert into recovery_receipt_difference(tenant_id,company_id,branch_id,plan_id,operation_id,classification,live_request_hash,candidate_request_hash)
   select :t,:c,:b,:plan,operation_id,classification,live_hash,candidate_hash from classified where classification is not null returning operation_id)
 select count(*) filter(where classification is null),count(*) filter(where classification is not null) from classified
 """;
 public Plan compare(UUID id,Compare input){if(input==null||input.fenceDecisionId()==null||input.fenceEpoch()<1)throw new IllegalArgumentException("Approved tenant fence receipt and epoch required");hash(input.candidateArtifactSha256());text(input.egressEvidenceReference(),1000);text(input.reason(),2000);number(input.version());return tx.execute(()->{authorize("operations:recovery:write");lifecycle.requireSuspended(input.fenceDecisionId(),input.fenceEpoch());return command(input.operationId(),"RecoveryCandidateCompared",List.of(id,input),Plan.class,input.reason(),()->{
  var p=find(id,LockModeType.PESSIMISTIC_WRITE);version(p,input.version());if(!p.status.equals("COLLECTING"))throw new IllegalStateException("Collecting candidate required");if(!p.actorId.equals(TenantContext.current().actorId()))throw new AccessDeniedException("Candidate maker required");var s=TenantContext.current();var cutoff=Instant.now().truncatedTo(ChronoUnit.MICROS);
  Object[] counts=(Object[])em.createNativeQuery(COMPARISON).setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("cut",cutoff).setParameter("plan",id).getSingleResult();p.matchCount=((Number)counts[0]).longValue();p.differenceCount=((Number)counts[1]).longValue();p.status=p.differenceCount==0?"MATCH_REVIEW_REQUIRED":"DIFFERENCES_QUARANTINED";p.fenceDecisionId=input.fenceDecisionId();p.fenceEpoch=input.fenceEpoch();p.candidateArtifactSha256=input.candidateArtifactSha256();p.egressEvidenceReference=input.egressEvidenceReference();p.comparedAt=cutoff;em.flush();return view(p);
 },Plan::id);});}
 public List<Difference> differences(UUID id,UUID after,int limit){if(limit<1||limit>500)throw new IllegalArgumentException("Page limit 1..500 required");return tx.execute(()->{authorize("operations:recovery:read");find(id,LockModeType.NONE);String sql="select operation_id,classification,live_request_hash,candidate_request_hash from recovery_receipt_difference where plan_id=:p"+(after==null?"":" and operation_id>:a")+" order by operation_id";var q=em.createNativeQuery(sql).setParameter("p",id).setMaxResults(limit);if(after!=null)q.setParameter("a",after);return ((List<?>)q.getResultList()).stream().map(o->{var r=(Object[])o;return new Difference((UUID)r[0],(String)r[1],(String)r[2],(String)r[3]);}).toList();});}
 public Plan approveReceiptReview(UUID id,Review input){review(input);return tx.execute(()->{authorize("operations:recovery:approve");var observed=find(id,LockModeType.NONE);if(observed.fenceDecisionId==null||observed.fenceEpoch==null)throw new IllegalStateException("Compared frozen candidate required");lifecycle.requireSuspended(observed.fenceDecisionId,observed.fenceEpoch);return command(input.operationId(),"RecoveryReceiptReviewApproved",List.of(id,input),Plan.class,input.reason(),()->{var p=find(id,LockModeType.PESSIMISTIC_WRITE);version(p,input.version());if(!p.status.equals("MATCH_REVIEW_REQUIRED")||p.differenceCount!=0)throw new IllegalStateException("Matching candidate receipts required");independent(p);var scope=TenantContext.current();Number changed=(Number)em.createNativeQuery("select count(*) from (select operation_id,request_hash,source_type,source_id,response_digest from recovery_retained_receipt_v1 where tenant_id=:t and company_id=:c and branch_id=:b) l full join (select operation_id,request_hash,source_type,source_id,response_digest from recovery_candidate_receipt where tenant_id=:t and company_id=:c and branch_id=:b and plan_id=:p) r on l.operation_id=r.operation_id where l.operation_id is null or r.operation_id is null or l.response_digest is null or r.response_digest is null or l.request_hash is distinct from r.request_hash or l.source_type is distinct from r.source_type or l.source_id is distinct from r.source_id or l.response_digest is distinct from r.response_digest").setParameter("t",scope.tenantId()).setParameter("c",scope.companyId()).setParameter("b",scope.branchId()).setParameter("p",id).getSingleResult();if(changed.longValue()!=0)throw new IllegalStateException("Retained source receipts changed after comparison; fresh candidate review required");p.reviewedBy=TenantContext.current().actorId();p.status="RECEIPTS_REVIEWED";em.flush();return view(p);},Plan::id);});}
 public Plan cancel(UUID id,Review input){review(input);return tx.execute(()->{authorize("operations:recovery:write");return command(input.operationId(),"RecoveryPlanCancelled",List.of(id,input),Plan.class,input.reason(),()->{var p=find(id,LockModeType.PESSIMISTIC_WRITE);version(p,input.version());if(Set.of("RECEIPTS_REVIEWED","CANCELLED").contains(p.status))throw new IllegalStateException("Final evidence remains retained");p.status="CANCELLED";em.flush();return view(p);},Plan::id);});}
 private RecoveryPlan find(UUID id,LockModeType lock){var s=TenantContext.current();var p=em.find(RecoveryPlan.class,new ScopeKey(s.tenantId(),s.companyId(),Objects.requireNonNull(id)),lock);if(p==null||!p.branchId.equals(s.branchId()))throw new NoSuchElementException("Recovery plan not found");return p;}
 private Plan view(RecoveryPlan p){return new Plan(p.id,p.incidentReference,p.targetPoint,p.sourceArtifactReference,p.status,p.actorId,p.scopeApprovedBy,p.reviewedBy,Long.toString(p.version),Integer.toString(p.nextBatch),Long.toString(p.candidateCount),Long.toString(p.matchCount),Long.toString(p.differenceCount),p.fenceDecisionId,p.fenceEpoch==null?null:Long.toString(p.fenceEpoch),p.candidateArtifactSha256,p.egressEvidenceReference,p.comparedAt,"PRESERVE_SOURCE_AND_CANDIDATE",false,false);}
 private void independent(RecoveryPlan p){if(p.actorId.equals(TenantContext.current().actorId()))throw new AccessDeniedException("Independent recovery reviewer required");}
 private void version(RecoveryPlan p,String version){if(p.version!=number(version))throw new RevisionConflict("Recovery plan changed");}
 private <T>T command(UUID op,String kind,Object material,Class<T> type,String reason,Supplier<T> action,Function<T,UUID> id){return receipts.once(op,kind,material,type,()->{T result=action.get();audit.append(op,kind,"recovery_plan",id.apply(result),reason);return result;},id);}
 private static void review(Review r){if(r==null)throw new IllegalArgumentException("Review required");text(r.reason(),2000);number(r.version());}
 private static void text(String s,int max){if(s==null||s.isBlank()||s.length()>max||s.indexOf('\0')>=0)throw new IllegalArgumentException("Bounded nonblank text required");}
 private static void hash(String s){if(s==null||!s.matches("[a-f0-9]{64}"))throw new IllegalArgumentException("Lowercase SHA-256 digest required");}
 private static long number(String s){if(s==null||!s.matches("0|[1-9][0-9]*"))throw new IllegalArgumentException("Nonnegative integer string required");return Long.parseLong(s);}
 private static void bounds(int offset,int limit){if(offset<0||offset>100000||limit<1||limit>100)throw new IllegalArgumentException("Invalid page bounds");}
}
